-- 214: Help Center — Canada's PIPEDA and Québec Law 25 in the data breaches topic and
-- the impact assessment questionnaires. Same pattern as db/204.
-- Safe to run more than once.

BEGIN;

CREATE TEMP TABLE _tr214 (key_code text, base_text text, ar_text text) ON COMMIT DROP;

INSERT INTO _tr214 (key_code, base_text, ar_text) VALUES
  ('helpdoc.data-breaches.summary', E'Record every breach of personal data, see which data and people it affects, and notify each regulator in time: within 72 hours under PDPL and GDPR, as soon as feasible under Canada''s laws.', E'سجّل كل خرق للبيانات الشخصية، واعرف البيانات والأشخاص الذين يمسّهم، وأشعر كل جهة مختصة في الوقت المحدد: خلال 72 ساعة وفق نظام حماية البيانات الشخصية واللائحة الأوروبية، وفي أقرب وقت ممكن وفق القوانين الكندية.'),
  ('helpdoc.data-breaches.what.body', E'The breach register under **Data Privacy › Data Breaches** records every suspected or confirmed breach of personal data, whether or not it has to be reported, as the Saudi PDPL, the GDPR, Canada''s PIPEDA and Québec''s Law 25 require. For each breach it keeps:\n- what happened, when the organisation became aware of it, the kind of breach and its cause;\n- the **laws that apply**, each with its own regulator and rule;\n- the **affected data**: the systems, tables or columns involved, with the catalog''s facts about the personal data in them (categories, sensitive data, row counts, copies elsewhere, sharing);\n- the **risk** to the people concerned;\n- the **notifications**: to each regulator, and to the people concerned;\n- the **measures** taken to contain it and prevent it happening again, and a timeline of every step.', E'يسجّل سجل الخروقات في **خصوصية البيانات › خروقات البيانات** كل خرق مشتبه به أو مؤكد للبيانات الشخصية، سواء وجب الإبلاغ عنه أم لا، كما يشترط نظام حماية البيانات الشخصية السعودي واللائحة الأوروبية وقانون PIPEDA الكندي وقانون 25 في كيبك. ويحفظ لكل خرق:\n- ما الذي حدث، ومتى علمت الجهة به، ونوع الخرق وسببه؛\n- **الأنظمة المنطبقة**، ولكل منها جهته المختصة وقاعدته؛\n- **البيانات المتأثرة**: الأنظمة أو الجداول أو الأعمدة المعنية، مع حقائق الكتالوج عن البيانات الشخصية فيها (الفئات، والبيانات الحساسة، وعدد الصفوف، والنسخ في أماكن أخرى، والمشاركة)؛\n- **الخطر** على أصحاب البيانات؛\n- **الإشعارات**: لكل جهة مختصة، ولأصحاب البيانات؛\n- **الإجراءات** المتخذة لاحتوائه ومنع تكراره، وسجلاً زمنياً لكل خطوة.'),
  ('helpdoc.data-breaches.value.body', E'- Meets each law''s duty to notify its regulator (within 72 hours under PDPL and GDPR, as soon as feasible under PIPEDA, promptly under Law 25) and to keep a record of every breach.\n- In minutes, the catalog shows which personal data was in the affected systems and how many people it may concern, instead of a manual investigation.\n- Deadline reminders, and a regulator report ready to send.', E'- يفي بواجب كل نظام في إشعار جهته المختصة (خلال 72 ساعة وفق نظام حماية البيانات الشخصية واللائحة الأوروبية، وفي أقرب وقت ممكن وفق قانون PIPEDA، وعلى وجه السرعة وفق قانون 25) وبحفظ سجل لكل خرق.\n- يعرض الكتالوج في دقائق البيانات الشخصية التي كانت في الأنظمة المتأثرة وعدد من قد يمسّهم الخرق، بدلاً من تحقيق يدوي.\n- تذكيرات بالمهلة، وتقرير جاهز لإرساله إلى الجهة المختصة.'),
  ('helpdoc.data-breaches.deadline.title', E'Laws, deadlines and what must be notified', E'الأنظمة والمُهل وما يجب الإشعار به'),
  ('helpdoc.data-breaches.deadline.body', E'Each breach lists the laws that apply. The laws preselected on a new breach are chosen by an administrator in Configuration › Privacy & Retention › Data breach laws; the handler can change them on the breach. Each law adds a notice to its regulator:\n\n| Law | Regulator | When to notify the regulator | Records |\n|---|---|---|---|\n| Saudi PDPL (Implementing Regulation, art. 24) | SDAIA | Within 72 hours of becoming aware, for any risk to people | — |\n| EU GDPR (art. 33–34) | Lead supervisory authority | Within 72 hours of becoming aware, unless unlikely to result in a risk | Every breach documented |\n| Canada PIPEDA (s. 10.1) | Office of the Privacy Commissioner | As soon as feasible, when there is a real risk of significant harm | Every breach kept 24 months |\n| Québec Law 25 (Private Sector Act, ss. 3.5–3.8) | Commission d''accès à l''information | Promptly, when there is a risk of serious injury | Every incident kept at least 5 years |\n\nDeadlines run from the time recorded as *When the organisation became aware*. Bayanis never deletes a breach, which meets every record-keeping period.\n\n| Risk to the people concerned | Regulators | Data subjects |\n|---|---|---|\n| Not assessed yet | Every notice is treated as required | — |\n| Unlikely to put people at risk | Not required under any law; record why | Not required |\n| Risk to people | Required under PDPL and GDPR; not under the Canadian laws | Not required |\n| High risk to people | Required under every law that applies | Required without undue delay, or record why not |\n\nUnder PIPEDA, *high risk* means a real risk of significant harm; under Law 25, a risk of serious injury.\n\nWhen the affected assets hold personal data, the catalog suggests a level: **High** for sensitive categories, large scale (100,000 rows or more) or unencrypted personal data columns, otherwise **Risk**; **Unlikely** when they hold none. The officer decides.\n\nThe register shows each notice as due, due within 24 hours, overdue, to notify as soon as feasible, or made on time or late. For the 72-hour laws, an hourly check reminds the handler and the compliance officers once when less than 24 hours are left and once when the deadline has passed (Configuration › Scheduling › Data breaches).', E'يذكر كل خرق الأنظمة المنطبقة عليه. ويختار مدير النظام الأنظمة المحددة مسبقاً للخرق الجديد من الإعدادات › الخصوصية والاحتفاظ › أنظمة خروقات البيانات، ويستطيع المسؤول عن المعالجة تغييرها في الخرق نفسه. ويضيف كل نظام إشعاراً لجهته المختصة:\n\n| النظام | الجهة المختصة | متى تُشعَر الجهة المختصة | السجلات |\n|---|---|---|---|\n| نظام حماية البيانات الشخصية السعودي (اللائحة التنفيذية، المادة 24) | سدايا | خلال 72 ساعة من العلم بالخرق، عند وجود أي خطر على الأشخاص | — |\n| اللائحة الأوروبية (المادتان 33 و34) | السلطة الإشرافية الرئيسية | خلال 72 ساعة من العلم بالخرق، ما لم يُستبعد أن يؤدي إلى خطر | توثيق كل خرق |\n| قانون PIPEDA الكندي (المادة 10.1) | مكتب مفوض الخصوصية | في أقرب وقت ممكن، عند وجود خطر حقيقي بضرر جسيم | حفظ كل خرق 24 شهراً |\n| قانون 25 في كيبك (قانون القطاع الخاص، المواد 3.5–3.8) | لجنة الوصول إلى المعلومات | على وجه السرعة، عند وجود خطر إلحاق ضرر جدي | حفظ كل حادث 5 سنوات على الأقل |\n\nتبدأ المُهل من الوقت المسجّل في *متى علمت الجهة بالخرق*. ولا يحذف بيانيس أي خرق أبداً، وبذلك يفي بكل مدد حفظ السجلات.\n\n| الخطر على أصحاب البيانات | الجهات المختصة | أصحاب البيانات |\n|---|---|---|\n| لم يُقيَّم بعد | يُعامل كل إشعار على أنه مطلوب | — |\n| لا يُرجَّح أن يعرّض الأشخاص للخطر | غير مطلوب وفق أي نظام، ويُسجَّل السبب | غير مطلوب |\n| خطر على الأشخاص | مطلوب وفق نظام حماية البيانات الشخصية واللائحة الأوروبية، لا وفق القوانين الكندية | غير مطلوب |\n| خطر مرتفع على الأشخاص | مطلوب وفق كل نظام منطبق | مطلوب دون تأخير غير مبرر، أو يُسجَّل سبب عدم الإبلاغ |\n\nفي قانون PIPEDA يعني *الخطر المرتفع* خطراً حقيقياً بضرر جسيم، وفي قانون 25 خطر إلحاق ضرر جدي.\n\nعندما تحوي الأصول المتأثرة بيانات شخصية، يقترح الكتالوج مستوى: **مرتفع** للفئات الحساسة أو النطاق الواسع (100,000 صف فأكثر) أو أعمدة البيانات الشخصية غير المشفرة، وإلا **خطر**؛ و**غير مرجَّح** عندما لا تحوي أي بيانات شخصية. والقرار لمسؤول الامتثال.\n\nيبيّن السجل كل إشعار بأنه مستحق، أو مستحق خلال 24 ساعة، أو متأخر، أو يجب في أقرب وقت ممكن، أو تم في الموعد أو متأخراً. وفي أنظمة الـ72 ساعة، يذكّر فحص كل ساعة المسؤولَ عن المعالجة ومسؤولي الامتثال مرة عندما يتبقى أقل من 24 ساعة، ومرة عند انقضاء المهلة (الإعدادات › الجدولة › خروقات البيانات).'),
  ('helpdoc.data-breaches.how.body', E'1. Anyone who suspects a breach reports it: **New Request › Report a data breach** (open to every user, also from a table''s New Request), or **Report a breach** on this page. A short description and when it became known are enough; compliance officers are notified at once.\n2. The compliance officer (or administrator) assigns a handler, checks the laws that apply, adds the affected assets and records the risk.\n3. For each law, notify its regulator and record when, with their reference; notify the data subjects when the risk is high. **Regulator report (PDF)** gives the details a notification asks for.\n4. Record the containment and prevention measures, then **Close** the breach. Bayanis lists anything still missing. A report that turns out not to involve personal data is closed as **Not a breach**.\n\nCompliance officers and administrators see every breach. The person who reported a breach, and its handler, see that breach; only officers, administrators and the handler can change it. Breaches are never deleted.', E'1. يبلّغ كل من يشتبه بخرق عنه: **طلب جديد › الإبلاغ عن خرق للبيانات** (متاح لكل مستخدم، ومن صفحة الجدول أيضاً عبر طلب جديد)، أو **الإبلاغ عن خرق** في هذه الصفحة. ويكفي وصف قصير ووقت العلم به، ويُشعَر مسؤولو الامتثال فوراً.\n2. يُسند مسؤول الامتثال (أو مدير النظام) مسؤولاً عن المعالجة، ويتحقق من الأنظمة المنطبقة، ويضيف الأصول المتأثرة، ويسجّل الخطر.\n3. لكل نظام، أشعر جهته المختصة وسجّل وقت الإشعار ورقم مرجعها، وأبلغ أصحاب البيانات عندما يكون الخطر مرتفعاً. ويوفر **تقرير الجهة المختصة (PDF)** التفاصيل التي يطلبها الإشعار.\n4. سجّل إجراءات الاحتواء والوقاية، ثم **أغلق** الخرق. ويعرض بيانيس ما ينقص إن وُجد. والبلاغ الذي يتبيّن أنه لا يمسّ بيانات شخصية يُغلق بوصفه **ليس خرقاً**.\n\nيرى مسؤولو الامتثال ومديرو النظام كل الخروقات. ويرى المُبلِّغ والمسؤول عن المعالجة الخرق الخاص بهما؛ ولا يغيّره إلا مسؤولو الامتثال ومديرو النظام والمسؤول عن المعالجة. ولا تُحذف الخروقات أبداً.'),
  ('helpdoc.impact-assessments.questionnaires.body', E'Four questionnaires come with Bayanis:\n- **Saudi PDPL**: one Yes in screening requires an assessment.\n- **GDPR Article 35**, with the WP248 criteria: two Yes require an assessment.\n- **Québec Law 25**: one Yes requires an assessment: a project to acquire, develop or overhaul a system holding personal information (s. 3.3), communication outside Québec (s. 17), or communication without consent for research (s. 21). The person in charge of the protection of personal information is consulted from the start.\n- **Canada PIPEDA**: questions follow the ten fair information principles. PIPEDA itself does not require an assessment; the Privacy Commissioner recommends one for new or changed programs, so here it is a recommendation.\n\nCompliance officers and administrators edit them under **Questionnaires**, in English; translations are made in Languages & Translations.\n\nWhich questionnaires are used, and the default, is chosen by an administrator in Configuration › Privacy & Retention. Edits apply to assessments not yet decided; questions already answered are retired rather than deleted.', E'يأتي بيانيس بأربعة استبيانات:\n- **نظام حماية البيانات الشخصية السعودي**: تكفي إجابة واحدة بنعم في الفحص لإلزام التقييم.\n- **اللائحة العامة لحماية البيانات - المادة 35** مع معايير الإرشاد WP248: تلزم إجابتان بنعم.\n- **قانون 25 في كيبك**: تكفي إجابة واحدة بنعم: مشروع لاقتناء نظام يحوي معلومات شخصية أو تطويره أو إعادة بنائه (المادة 3.3)، أو الإفصاح خارج كيبك (المادة 17)، أو الإفصاح دون موافقة لأغراض البحث (المادة 21). ويُستشار المسؤول عن حماية المعلومات الشخصية منذ البداية.\n- **قانون PIPEDA الكندي**: تتبع الأسئلة مبادئ المعالجة العادلة للمعلومات العشرة. ولا يشترط القانون نفسه التقييم، لكن مفوض الخصوصية يوصي به للبرامج الجديدة أو المعدلة، لذا يكون هنا توصية.\n\nيعدّلها مسؤولو الامتثال ومديرو النظام من **الاستبيانات** باللغة الإنجليزية، وتُترجم في اللغات والترجمات.\n\nويختار مدير النظام الاستبيانات المستخدمة والاستبيان الافتراضي من الإعدادات › الخصوصية والاحتفاظ. وتنطبق التعديلات على التقييمات التي لم يُبتّ فيها بعد، والأسئلة التي أُجيب عنها تُوقف بدلاً من حذفها.');

-- Human work on the old English is kept (marked out of date below), never overwritten.
CREATE TEMP TABLE _keep214 ON COMMIT DROP AS
SELECT tr.key_id FROM bayanat.translations tr
JOIN bayanat.translation_keys tk ON tk.key_id = tr.key_id
JOIN _tr214 n ON n.key_code = tk.key_code
WHERE tr.language_code = 'ar' AND tr.status_code IN ('HUMAN_EDITED', 'VERIFIED') AND tk.base_text <> n.base_text;

UPDATE bayanat.translations tr SET status_code = 'STALE'
FROM bayanat.translation_keys tk, _tr214 n
WHERE tr.key_id = tk.key_id AND tk.key_code = n.key_code AND tk.base_text <> n.base_text AND tr.status_code <> 'MISSING';

UPDATE bayanat.translation_keys tk SET base_text = n.base_text
FROM _tr214 n WHERE tk.key_code = n.key_code AND tk.base_text <> n.base_text;

INSERT INTO bayanat.translation_keys (category_code, key_code, base_text)
SELECT 'HELP_DOCS', key_code, base_text FROM _tr214
ON CONFLICT (key_code) DO NOTHING;

INSERT INTO bayanat.translations (key_id, language_code, translated_text, status_code, model_ref_text, translated_at)
SELECT tk.key_id, 'ar', n.ar_text, 'AI_TRANSLATED', 'Anthropic Claude:claude-opus-5-5', now()
FROM _tr214 n
JOIN bayanat.translation_keys tk ON tk.key_code = n.key_code AND tk.base_text = n.base_text
WHERE tk.key_id NOT IN (SELECT key_id FROM _keep214)
ON CONFLICT (key_id, language_code) DO UPDATE
  SET translated_text = EXCLUDED.translated_text, status_code = 'AI_TRANSLATED',
      model_ref_text = EXCLUDED.model_ref_text, translated_at = now(), verified_at = NULL, verified_by_user_id = NULL
  WHERE bayanat.translations.status_code IN ('MISSING', 'STALE', 'AI_TRANSLATED')
     OR bayanat.translations.translated_text IS NULL;

COMMIT;
